    "property_id": "PROP-6a4369e9-inv-035",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-035",
      "classification": "vulnerability",
      "code_path": "beacon_node/network/src/network_beacon_processor/rpc_methods.rs::handle_blobs_by_root_request_inner::L289-366",
      "proof_trace": "Handler lacks epoch-based deprecation check. After FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS, the handler continues processing BlobsByRoot requests normally instead of rejecting them. No validation compares current_epoch against fulu_fork_epoch + min_epochs_for_blob_sidecars_requests threshold.",
      "attack_scenario": "After deprecation threshold (FULU_FORK_EPOCH + 4096 epochs), any peer sends BlobsByRoot RPC request. Node processes it normally via handle_blobs_by_root_request_inner, responding with blobs if available, violating protocol spec deprecation requirement. Causes protocol non-compliance and resource waste on deprecated endpoints.",
      "checklist_id": "PROP-6a4369e9-inv-035"
    },
    "text": "blob_sidecars_by_root must be fully deprecated after FULU_FORK_EPOCH + MIN_EPOCHS.",
    "assertion": "current_epoch >= FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS => respond_empty_or_reject",
    "covers": "SG-013",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

